def solve_linear(arr, l: int, r: int) -> int:
    prev2 = 0
    prev1 = 0
    for i in range(l, r + 1):
        cand = prev2 + arr[i]
        cur = cand if cand > prev1 else prev1
        prev2 = prev1
        prev1 = cur
    return prev1


