int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    const int MOD = 1000000007;
    vector<long long> dp(m, 0);
    vector<int> cnt(m, 0);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            long long val;
            cin >> val;
            if (i == 0 && j == 0) {
                dp[0] = val;
                cnt[0] = 1;
            } else if (i == 0) {
                dp[j] = dp[j - 1] + val;
                cnt[j] = 1;
            } else if (j == 0) {
                dp[0] = dp[0] + val;
                // cnt[0] stays 1
            } else {
                long long top = dp[j];
                long long left = dp[j - 1];
                if (top > left) {
                    dp[j] = top + val;
                } else if (left > top) {
                    dp[j] = left + val;
                    cnt[j] = cnt[j - 1];
                } else {
                    dp[j] = top + val;
                    int s = cnt[j] + cnt[j - 1];
                    if (s >= MOD) s -= MOD;
                    cnt[j] = s;
                }
            }
        }
    }

    cout << dp[m - 1] << ' ' << cnt[m - 1] << '\n';
    return 0;
}
