            int w = ways[x] + ways[x - c];
            if (w >= MOD) w -= MOD;
            ways[x] = w;
        }
    }

    cout << (min_coins[S] >= INF ? -1 : min_coins[S]) << '\n';
    cout << ways[S] << '\n';
    return 0;
}
