int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<vector<long long>> c(n, vector<long long>(n));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> c[i][j];

    int m = n - 1;
    int full = (1 << m) - 1;
    const long long INF = (1LL << 60);

    vector<vector<long long>> dp(1 << m, vector<long long>(m, INF));
    for (int u = 0; u < m; ++u) {
        dp[1 << u][u] = c[0][u + 1];
    }

    for (int mask = 1; mask <= full; ++mask) {
        int unvis = full ^ mask;
        if (unvis == 0) continue;
        for (int u = 0; u < m; ++u) {
            if (!((mask >> u) & 1)) continue;
            long long cur = dp[mask][u];
            if (cur >= INF) continue;
            int rem = unvis;
            while (rem) {
                int lb = rem & -rem;
                int v = __builtin_ctz(lb);
                long long cand = cur + c[u + 1][v + 1];
                if (cand < dp[mask | lb][v]) {
                    dp[mask | lb][v] = cand;
                }
                rem ^= lb;
            }
        }
    }

    long long ans = INF;
    for (int u = 0; u < m; ++u) {
        ans = min(ans, dp[full][u] + c[u + 1][0]);
    }
    cout << ans << '\n';
    return 0;
}
