    bit_idx = {1 << i: i for i in range(m)}

    for mask in range(1, full):
        dp_mask = dp[mask]
        unvis = full ^ mask
        rem_u = mask
        while rem_u:
            lb_u = rem_u & -rem_u
            rem_u ^= lb_u
            u = bit_idx[lb_u]
            cur = dp_mask[u]
            if cur >= INF:
