                lb_v = rem_v & -rem_v
                rem_v ^= lb_v
                v = bit_idx[lb_v]
                nxt_row = dp[mask | lb_v]
                cand = cur + row_u[v + 1]
                if cand < nxt_row[v]:
                    nxt_row[v] = cand

    dp_full = dp[full]
    ans = INF
    for u in range(m):
        cand = dp_full[u] + c[u + 1][0]
        if cand < ans:
            ans = cand
